/**
 * Fixed-capacity LRU cache backed by a hash map and an intrusive doubly
 * linked list stored in typed arrays. All operations are O(1) expected.
 */
const NIL = -1;

export class LruCache {
  readonly #capacity: number;
  readonly #index = new Map<string, number>();
  readonly #keys: string[];
  readonly #values: string[];
  readonly #prev: Int32Array;
  readonly #next: Int32Array;
  #head = NIL; // most recently used
  #tail = NIL; // least recently used
  #freeTop = NIL; // stack of reusable slots, linked through #next
  #used = 0; // slots handed out so far (high-water mark)

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError(`invalid capacity: ${capacity}`);
    }
    this.#capacity = capacity;
    this.#keys = new Array<string>(capacity);
    this.#values = new Array<string>(capacity);
    this.#prev = new Int32Array(capacity);
    this.#next = new Int32Array(capacity);
  }

  get size(): number {
    return this.#index.size;
  }

  get(key: string): string | undefined {
    const slot = this.#index.get(key);
    if (slot === undefined) return undefined;
    this.#moveToFront(slot);
    return this.#values[slot];
  }

  set(key: string, value: string): void {
    const existing = this.#index.get(key);
    if (existing !== undefined) {
      this.#values[existing] = value;
      this.#moveToFront(existing);
      return;
    }
    if (this.#index.size >= this.#capacity) this.#evict();
    const slot = this.#allocate();
    this.#keys[slot] = key;
    this.#values[slot] = value;
    this.#index.set(key, slot);
    this.#pushFront(slot);
  }

  delete(key: string): boolean {
    const slot = this.#index.get(key);
    if (slot === undefined) return false;
    this.#index.delete(key);
    this.#unlink(slot);
    this.#release(slot);
    return true;
  }

  #evict(): void {
    const slot = this.#tail;
    this.#index.delete(this.#keys[slot]);
    this.#unlink(slot);
    this.#release(slot);
  }

  #allocate(): number {
    if (this.#freeTop !== NIL) {
      const slot = this.#freeTop;
      this.#freeTop = this.#next[slot];
      return slot;
    }
    return this.#used++;
  }

  #release(slot: number): void {
    // Drop references so evicted strings can be collected.
    this.#keys[slot] = "";
    this.#values[slot] = "";
    this.#next[slot] = this.#freeTop;
    this.#freeTop = slot;
  }

  #pushFront(slot: number): void {
    this.#prev[slot] = NIL;
    this.#next[slot] = this.#head;
    if (this.#head !== NIL) this.#prev[this.#head] = slot;
    else this.#tail = slot;
    this.#head = slot;
  }

  #unlink(slot: number): void {
    const p = this.#prev[slot];
    const n = this.#next[slot];
    if (p !== NIL) this.#next[p] = n;
    else this.#head = n;
    if (n !== NIL) this.#prev[n] = p;
    else this.#tail = p;
  }

  #moveToFront(slot: number): void {
    if (slot === this.#head) return;
    this.#unlink(slot);
    this.#pushFront(slot);
  }
}

import { readFileSync, writeSync } from "node:fs";
import { LruCache } from "./lru.ts";

function readStdin(): string {
  try {
    return readFileSync(0, "latin1");
  } catch (err) {
    // An empty or closed stdin is treated as no input.
    if ((err as NodeJS.ErrnoException).code === "EAGAIN" || (err as NodeJS.ErrnoException).code === "EOF") return "";
    throw err;
  }
}

function writeAll(text: string): void {
  const buf = Buffer.from(text, "latin1");
  let offset = 0;
  while (offset < buf.length) {
    try {
      offset += writeSync(1, buf, offset);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== "EAGAIN") throw err;
    }
  }
}

function run(input: string): string {
  const lines = input.split("\n");
  const capacity = Number.parseInt(lines[0] ?? "", 10);
  if (!Number.isInteger(capacity) || capacity < 1) return "";

  const cache = new LruCache(capacity);
  const out: string[] = [];

  for (let i = 1; i < lines.length; i++) {
    let line = lines[i];
    if (line.endsWith("\r")) line = line.slice(0, -1);
    if (line.length === 0) continue;

    const sp1 = line.indexOf(" ");
    const cmd = sp1 === -1 ? line : line.slice(0, sp1);
    switch (cmd) {
      case "SET": {
        const sp2 = line.indexOf(" ", sp1 + 1);
        if (sp2 === -1) break;
        cache.set(line.slice(sp1 + 1, sp2), line.slice(sp2 + 1));
        break;
      }
      case "GET":
        if (sp1 !== -1) out.push(cache.get(line.slice(sp1 + 1)) ?? "NULL");
        break;
      case "DEL":
        if (sp1 !== -1) out.push(cache.delete(line.slice(sp1 + 1)) ? "1" : "0");
        break;
      case "SIZE":
        out.push(String(cache.size));
        break;
      default:
        // Unknown commands are ignored.
        break;
    }
  }

  return out.length === 0 ? "" : out.join("\n") + "\n";
}

writeAll(run(readStdin()));
